class Solution {
    long long modPow(long long base, long long exp, long long mod) {
        long long res = 1;
        base %= mod;
        while (exp > 0) {
            if (exp & 1) res = (__int128)res * base % mod;
            base = (__int128)base * base % mod;
            exp >>= 1;
        }
        return res;
    }
public:
    int minNonZeroProduct(int p) {
        if (p == 1) return 1;
        long long mod = 1e9 + 7;
        long long maxVal = ((1LL << (p - 1)) - 1) * 2 + 1; // 2^p - 1
        long long val = maxVal - 1; // 2^p - 2
        long long cnt = (1LL << (p - 1)) - 1;
        long long ans = modPow(val, cnt, mod);
        ans = (__int128)ans * (maxVal % mod) % mod;
        return ans;
    }
};

class Solution {
    private long modPow(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (long)((java.math.BigInteger.valueOf(res).multiply(java.math.BigInteger.valueOf(base))).mod(java.math.BigInteger.valueOf(mod)).longValue());
            base = (long)((java.math.BigInteger.valueOf(base).multiply(java.math.BigInteger.valueOf(base))).mod(java.math.BigInteger.valueOf(mod)).longValue());
            exp >>= 1;
        }
        return res;
    }
    public int minNonZeroProduct(int p) {
        if (p == 1) return 1;
        long mod = 1_000_000_007;
        long maxVal = (1L << p) - 1;
        long val = maxVal - 1;
        long cnt = (1L << (p - 1)) - 1;
        long ans = modPow(val, cnt, mod);
        ans = (ans * (maxVal % mod)) % mod;
        return (int) ans;
    }
}

var minNonZeroProduct = function(p) {
  if (p === 1) return 1;
  const mod = 1000000007n;
  const P = BigInt(p);
  const maxVal = (1n << P) - 1n;
  const val = maxVal - 1n;
  const cnt = (1n << (P - 1n)) - 1n;

  const modPow = (b, e, m) => {
    let res = 1n;
    b = b % m;
    while (e > 0n) {
      if (e & 1n) res = (res * b) % m;
      b = (b * b) % m;
      e >>= 1n;
    }
    return res;
  };

  const ans = (modPow(val, cnt, mod) * (maxVal % mod)) % mod;
  return Number(ans);
};
